# Shorthand aliases for built-in types (convenience/minor speedup)
mem   = memoryview
array = bytearray

# Store unique command-line arguments for O(1) lookups
_argv = set(sys.argv[1 :])




# Supported feature switches
_ELFLDR_FLAGS = (
    '--help',
    '--obf', 
    '--debug', 
    '--vm'
)

# Parse active flags from CLI arguments
FLAG_HELP  : bool = _ELFLDR_FLAGS[0] in _argv
FLAG_OBF   : bool = _ELFLDR_FLAGS[1] in _argv
FLAG_DEBUG : bool = _ELFLDR_FLAGS[2] in _argv
FLAG_VM    : bool = _ELFLDR_FLAGS[3] in _argv

# Strip operational flags out 
# leaving only the target payload paths in _argv
for f in _ELFLDR_FLAGS: _argv.discard(f)
del f,   _ELFLDR_FLAGS




# Temporary build directory (hex token used to avoid collision)
PATH_DIR      : bytes = b'./_mkelfldr-%x' % 0 # % int(time())

# Intermediate build artifacts
PATH_LINK_LD  : bytes = PATH_DIR + b'/link.ld'
PATH_PAYLOAD  : bytes = PATH_DIR + b'/payload.bin'
PATH_LOADER_C : bytes = PATH_DIR + b'/loader.c'
PATH_ELFSTRIP : bytes = PATH_DIR + b'/elfstrip'

# Output configurations and signature marking
PATH_OUTPUT   : bytes = b'./elfldr-%b'
PATH_LABEL    : bytes = b'/*--GENERATED_BY_ELFLDR_FOR_FILE(%b)--*/'




